            sql="\nCREATE TABLE audit_log (\n  id uuid NOT NULL DEFAULT uuid_v7(),\n  occurred_at timestamptz NOT NULL,\n  actor_type varchar(7) NOT NULL,\n  actor_pseudonym uuid,\n  subject_pseudonym uuid,\n  represented_profile_pseudonym uuid,\n  action varchar(100) NOT NULL,\n  resource_type varchar(100) NOT NULL,\n  result varchar(7) NOT NULL,\n  category varchar(14) NOT NULL,\n  request_id varchar(64),\n  safe_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  enc_parts jsonb NOT NULL DEFAULT '[]'::jsonb,\n  CONSTRAINT audit_log_actor_type CHECK (actor_type IN ('USER', 'MANAGER', 'ADMIN', 'SYSTEM')),\n  CONSTRAINT audit_log_result CHECK (result IN ('SUCCESS', 'FAILURE', 'DENIED')),\n  CONSTRAINT audit_log_category CHECK (category IN\n    ('SYSTEM', 'FINANCIAL', 'ADMINISTRATIVE', 'STATE_CHANGE', 'SECURITY')),\n  CONSTRAINT audit_log_action_code CHECK (action ~ '^[a-z][a-z0-9_.]{1,99}$'),\n  CONSTRAINT audit_log_resource_code CHECK (resource_type ~ '^[a-z][a-z0-9_.]{1,99}$'),\n  CONSTRAINT audit_log_metadata_object CHECK (jsonb_typeof(safe_metadata) = 'object'),\n  CONSTRAINT audit_log_id_is_v7 CHECK (\n    substring(id::text, 15, 1) = '7' AND substring(id::text, 20, 1) IN ('8', '9', 'a', 'b')),\n  PRIMARY KEY (id)\n) PARTITION BY RANGE (id);\nCREATE INDEX audit_log_subject_time ON audit_log (subject_pseudonym, occurred_at);\nCREATE INDEX audit_log_actor_time ON audit_log (actor_pseudonym, occurred_at);\nCREATE INDEX audit_log_action_time ON audit_log (action, occurred_at);\nCREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON audit_log\n  FOR EACH ROW EXECUTE FUNCTION reject_row_change();\nCREATE TRIGGER audit_log_enc_parts BEFORE INSERT ON audit_log\n  FOR EACH ROW EXECUTE FUNCTION check_enc_parts();\nSELECT ensure_uuid7_partitions('audit_log', 'month', 3);\n\n-- Held events (TR-23): unpartitioned copy of events from dropped partitions.\nCREATE TABLE audit_log_hold (\n  id uuid NOT NULL DEFAULT uuid_v7(),\n  occurred_at timestamptz NOT NULL,\n  actor_type varchar(7) NOT NULL,\n  actor_pseudonym uuid,\n  subject_pseudonym uuid,\n  represented_profile_pseudonym uuid,\n  action varchar(100) NOT NULL,\n  resource_type varchar(100) NOT NULL,\n  result varchar(7) NOT NULL,\n  category varchar(14) NOT NULL,\n  request_id varchar(64),\n  safe_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,\n  enc_parts jsonb NOT NULL DEFAULT '[]'::jsonb,\n  retain_until timestamptz,\n  moved_at timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT audit_log_hold_actor_type CHECK (actor_type IN ('USER', 'MANAGER', 'ADMIN', 'SYSTEM')),\n  CONSTRAINT audit_log_hold_result CHECK (result IN ('SUCCESS', 'FAILURE', 'DENIED')),\n  CONSTRAINT audit_log_hold_category CHECK (category IN\n    ('SYSTEM', 'FINANCIAL', 'ADMINISTRATIVE', 'STATE_CHANGE', 'SECURITY')),\n  CONSTRAINT audit_log_hold_action_code CHECK (action ~ '^[a-z][a-z0-9_.]{1,99}$'),\n  CONSTRAINT audit_log_hold_resource_code CHECK (resource_type ~ '^[a-z][a-z0-9_.]{1,99}$'),\n  CONSTRAINT audit_log_hold_metadata_object CHECK (jsonb_typeof(safe_metadata) = 'object'),\n  PRIMARY KEY (id)\n);\nCREATE TABLE audit_log_hold_link (\n  event_id uuid NOT NULL,\n  hold_case_id uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (event_id, hold_case_id)\n);\nCREATE INDEX audit_log_hold_link_case ON audit_log_hold_link (hold_case_id);\n\n-- Hold rows and links: no UPDATE; DELETE only by the table owner, i.e. inside the\n-- SECURITY DEFINER maintenance functions below (the application role is not the owner, D-11).\nCREATE FUNCTION audit_hold_guard() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n  IF TG_OP = 'UPDATE' THEN\n    RAISE EXCEPTION '%: UPDATE rejected', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';\n  END IF;\n  IF current_user <> (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid = TG_RELID) THEN\n    RAISE EXCEPTION '%: DELETE only through the maintenance functions', TG_TABLE_NAME\n      USING ERRCODE = 'insufficient_privilege';\n  END IF;\n  RETURN OLD;\nEND $$;\nCREATE TRIGGER audit_log_hold_guard BEFORE UPDATE OR DELETE ON audit_log_hold\n  FOR EACH ROW EXECUTE FUNCTION audit_hold_guard();\nCREATE TRIGGER audit_log_hold_link_guard BEFORE UPDATE OR DELETE ON audit_log_hold_link\n  FOR EACH ROW EXECUTE FUNCTION audit_hold_guard();\n\nCREATE VIEW audit_log_all AS\n  SELECT id, occurred_at, actor_type, actor_pseudonym, subject_pseudonym, represented_profile_pseudonym, action, resource_type, result, category, request_id, safe_metadata, enc_parts, false AS held FROM audit_log\n  UNION ALL\n  SELECT id, occurred_at, actor_type, actor_pseudonym, subject_pseudonym, represented_profile_pseudonym, action, resource_type, result, category, request_id, safe_metadata, enc_parts, true AS held FROM audit_log_hold;\n\n-- Copy linked (held) events out of a past monthly partition, then detach and drop it, in one\n-- transaction. Maintenance role only (doc 09 records the operation; TR-24).\nCREATE FUNCTION archive_and_drop_audit_partition(p_partition regclass, p_retain_until timestamptz)\nRETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  moved integer;\n  month_start date;\nBEGIN\n  IF NOT EXISTS (SELECT 1 FROM pg_inherits\n                 WHERE inhrelid = p_partition AND inhparent = 'audit_log'::regclass) THEN\n    RAISE EXCEPTION 'not a partition of audit_log';\n  END IF;\n  month_start := to_date(right(p_partition::text, 7), 'YYYY_MM');\n  IF month_start + interval '1 month' > date_trunc('month', now() AT TIME ZONE 'UTC') THEN\n    RAISE EXCEPTION 'only past partitions can be dropped';\n  END IF;\n  EXECUTE format(\n    'INSERT INTO audit_log_hold (id, occurred_at, actor_type, actor_pseudonym, subject_pseudonym, represented_profile_pseudonym, action, resource_type, result, category, request_id, safe_metadata, enc_parts, retain_until)\n     SELECT p.id, p.occurred_at, p.actor_type, p.actor_pseudonym, p.subject_pseudonym, p.represented_profile_pseudonym, p.action, p.resource_type, p.result, p.category, p.request_id, p.safe_metadata, p.enc_parts, $1 FROM %s p\n     WHERE EXISTS (SELECT 1 FROM audit_log_hold_link l WHERE l.event_id = p.id)\n     ON CONFLICT (id) DO NOTHING', p_partition) USING p_retain_until;\n  GET DIAGNOSTICS moved = ROW_COUNT;\n  EXECUTE format('ALTER TABLE audit_log DETACH PARTITION %s', p_partition);\n  EXECUTE format('DROP TABLE %s', p_partition);\n  RETURN moved;\nEND $$;\nREVOKE ALL ON FUNCTION archive_and_drop_audit_partition(regclass, timestamptz) FROM PUBLIC;\n\n-- Release a hold: remove its links, then delete held rows with no remaining link, whose\n-- pseudonyms are under no other active hold, and whose retention has passed (doc 03 §22.15).\nCREATE FUNCTION release_held_events(p_hold_case uuid)\nRETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  removed integer;\nBEGIN\n  DELETE FROM audit_log_hold_link WHERE hold_case_id = p_hold_case;\n  DELETE FROM audit_log_hold h\n   WHERE NOT EXISTS (SELECT 1 FROM audit_log_hold_link l WHERE l.event_id = h.id)\n     AND h.retain_until IS NOT NULL AND h.retain_until <= now()\n     AND NOT EXISTS (\n       SELECT 1 FROM accounts_subject_pseudonym s\n        WHERE s.hold_ref IS NOT NULL\n          AND s.pseudonym IN (h.actor_pseudonym, h.subject_pseudonym,\n                              h.represented_profile_pseudonym));\n  GET DIAGNOSTICS removed = ROW_COUNT;\n  RETURN removed;\nEND $$;\nREVOKE ALL ON FUNCTION release_held_events(uuid) FROM PUBLIC;\n",
